"""Independently rebuild integer answers, score gates, and verify selection."""
import hashlib
import json
import re
import sys
from collections import Counter
from fractions import Fraction
from pathlib import Path


MAX_TOKENS = 512
LEVELS = ("L1", "L2", "L3")


def last_box(text):
    pattern = r"\\boxed\s*\{\s*([+-]?[0-9]+(?:,[0-9]{3})*(?:\.[0-9]+)?)\s*\}"
    for value in reversed(re.findall(pattern, text)):
        fraction = Fraction(value.replace(",", ""))
        if fraction.denominator == 1:
            return fraction.numerator
    return None


def read(path):
    return json.loads(path.read_bytes())


def fingerprint(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def independently_calculate(start, operations):
    value = start
    for plus, multiplier, deduction, divisor in operations:
        fraction = Fraction(value + plus) * multiplier - deduction
        # Reconstruct Euclidean quotient using an independent rational path.
        fraction /= divisor
        quotient = int(fraction)
        assert quotient <= fraction < quotient + 1
        value = quotient
    return value


def check_panels(panels):
    names = {"screen", "confirmation", "adaptation", "transfer"}
    assert set(panels) == names
    seen, ids = set(), set()
    for panel in panels.values():
        assert set(panel) == set(LEVELS)
        for rounding, name in enumerate(LEVELS, 1):
            rows = panel[name]
            assert len(rows) == 16
            assert Counter(row["family"] for row in rows) == {"register": 8, "packing": 8}
            for one, two in zip(rows[::2], rows[1::2], strict=True):
                assert one["pair"] == two["pair"] and one["family"] == two["family"]
                assert one["operations"] == two["operations"] and len(one["operations"]) == rounding
                assert one["gold"] != two["gold"] and one["start"] != two["start"]
                assert one["side"] == 0 and two["side"] == 1
                assert one["question"].replace(str(one["start"]), "START", 1) == two["question"].replace(str(two["start"]), "START", 1)
                displayed = [value for step in one["operations"] for value in step]
                assert {one["gold"], two["gold"]}.isdisjoint([*displayed, one["start"], two["start"]])
                for entry in (one, two):
                    low, high = 10 ** (rounding + 1), 10 ** (rounding + 2) - 1
                    assert low <= entry["start"] <= high
                    actual = list(map(int, re.findall(r"\b\d+\b", entry["question"])))
                    assert actual == [entry["start"], *displayed]
                    assert independently_calculate(entry["start"], entry["operations"]) == entry["gold"]
                    assert entry["question"] not in seen and entry["id"] not in ids
                    seen.add(entry["question"])
                    ids.add(entry["id"])
    assert len(seen) == 192
    return len(seen)


def exact_test(deltas):
    nonzero = [value for value in deltas if value]
    possible = [0]
    for change in nonzero:
        possible = [candidate for value in possible for candidate in (value - change, value + change)]
    tail = sum(value >= sum(nonzero) for value in possible)
    return {"p": tail / len(possible), "exact_tail": tail, "denominator": len(possible)}


def validate_prompt_records(rows, prediction):
    assert len(rows) == len(prediction) == 16
    for source, sample in zip(rows, prediction, strict=True):
        assert sample["id"] == source["id"] and sample["gold"] == source["gold"]
        assert all(len(sample[key]) == 4 for key in ("tokens", "masks", "text", "answers", "rewards", "lengths"))
        for seq, mask, n in zip(sample["tokens"], sample["masks"], sample["lengths"], strict=True):
            p = sample["prompt_length"]
            assert len(seq) == len(mask) == p + n and 0 <= n <= MAX_TOKENS
            assert mask == [0] * p + [1] * n


def score(rows, prediction):
    validate_prompt_records(rows, prediction)
    constant = Counter(row["gold"] for row in rows).most_common(1)[0][1] * 4
    correct = swapped = mixed = parseable = capped = 0
    wins, changes = set(), []
    for index in range(0, len(rows), 2):
        one, two = rows[index:index+2]
        delta = 0
        for source, other, observed in ((one, two, prediction[index]), (two, one, prediction[index+1])):
            reported = [last_box(text) for text in observed["text"]]
            assert reported == observed["answers"]
            rewards = [int(value == source["gold"]) for value in reported]
            assert rewards == observed["rewards"]
            good = sum(rewards)
            fake = sum(value == other["gold"] for value in reported)
            correct += good
            swapped += fake
            mixed += 0 < good < 4
            parseable += sum(value is not None for value in reported)
            capped += observed["lengths"].count(MAX_TOKENS)
            if good:
                wins.add(source["gold"])
            delta += good - fake
        changes.append(delta)
    test = exact_test(changes)
    gates = {"parseable": parseable >= 48, "correct": correct >= 16, "mixed": mixed >= 4,
             "distinct_targets": len(wins) >= 4, "constant": correct > constant, "paired_gap": correct - swapped >= 8,
             "p": test["exact_tail"] * 40 <= test["denominator"]}
    return {"passed": all(gates.values()), "gates": gates, "correct": correct, "parseable": parseable,
            "mixed_groups": mixed, "constant_correct": constant, "exchanged_correct": swapped,
            "distinct_correct_values": len(wins), "capped": capped, "questions": 16, "samples": 64,
            "paired_differences": changes, "paired_test": test}


def choose_level(panels, raw):
    scores = {name: score(panels["screen"][name], raw[name]) for name in LEVELS}
    return next((name for name in LEVELS if scores[name]["passed"]), None), scores


def audit(panel_file, observations):
    directory, trial = read(panel_file), read(observations)
    n = check_panels(directory["panels"])
    assert directory["seed"] == 811023 and trial["panels_sha256"] == fingerprint(panel_file)
    selected, screening = choose_level(directory["panels"], trial["screen"])
    assert selected == trial["selected_level"]
    checked = None
    if selected is not None:
        assert set(trial["confirmation"]) == {selected}
        checked = score(directory["panels"]["confirmation"][selected], trial["confirmation"][selected])
    else:
        assert not trial["confirmation"]
    return {"questions_verified": n, "panels_sha256": trial["panels_sha256"], "screening": screening,
            "selected_level": selected, "confirmation": checked, "qualified": bool(checked and checked["passed"])}


if __name__ == "__main__":
    panel, observations, destination = (Path(value) for value in sys.argv[1:])
    destination.write_text(json.dumps(audit(panel, observations), sort_keys=True, indent=2) + "\n")

