"""Generate the four sealed arithmetic panels without importing a model."""
import hashlib
import json
import random
import sys
from pathlib import Path


SEED = 811023
PANEL_NAMES = ("screen", "confirmation", "adaptation", "transfer")
LEVELS = {
    "L1": (100, 999, 1, 9, 17),
    "L2": (1_000, 9_999, 2, 31, 41),
    "L3": (10_000, 99_999, 3, 71, 79),
}
FAMILIES = ("register", "packing")


def operations(rng, low, rounds, mult_max, div_max):
    return [[rng.randint(low // 5, low * 2), rng.randint(3, mult_max),
             rng.randint(low // 8, low), rng.randint(3, div_max)] for _ in range(rounds)]


def execute(start, groups):
    current = start
    for add, times, subtract, divide in groups:
        numerator = (current + add) * times - subtract
        assert numerator >= 0
        current = numerator // divide
    return current


def render(alias, family, start, rounds):
    if family == "register":
        lines = [f"The first value in register {alias} is {start}. The register uses only whole numbers."]
        for add, times, subtract, divide in rounds:
            lines.append(f"Add {add}, multiply the result by {times}, subtract {subtract}, "
                         f"then divide by {divide} and round down to a whole number.")
        lines.append("Carry out the instructions in order. What is the final value in the register?")
    else:
        lines = [f"Workshop {alias} starts with {start} components."]
        for add, times, subtract, divide in rounds:
            lines.append(f"First receive {add} more components. Make {times} copies of the resulting inventory "
                         f"in total, including the original. Then discard {subtract} components. "
                         f"Pack the rest in boxes of {divide}, and ignore any incomplete box. "
                         "The number of full boxes becomes the starting count for the next round.")
        lines.append("How many full boxes are there in the last round?")
    return "\n".join(lines)


def build():
    rng = random.Random(SEED)
    result = {}
    for panel in PANEL_NAMES:
        result[panel] = {}
        for level, (low, high, rounds, mult_max, div_max) in LEVELS.items():
            rows = []
            for family in FAMILIES:
                for index in range(4):
                    while True:
                        a = rng.randint(low, high)
                        b = rng.randint(low, high)
                        groups = operations(rng, low, rounds, mult_max, div_max)
                        right = [execute(value, groups) for value in (a, b)]
                        displayed = set([a, b] + [v for group in groups for v in group])
                        if len(set(right)) == 2 and displayed.isdisjoint(right):
                            break
                    pair = f"{panel}.{level}.{family}.{index}"
                    alias = rng.choice(("Alder", "Birch", "Copper", "Juniper", "Larch", "Tamarack"))
                    for side, beginning in enumerate((a, b)):
                        rows.append({"id": f"{pair}.{side}", "pair": pair, "family": family,
                                     "side": side, "start": beginning, "operations": groups,
                                     "question": render(alias, family, beginning, groups), "gold": right[side]})
            result[panel][level] = rows
    return {"seed": SEED, "panels": result}


if __name__ == "__main__":
    output = Path(sys.argv[1])
    exact = json.dumps(build(), sort_keys=True, separators=(",", ":")).encode() + b"\n"
    with output.open("xb") as stream:
        stream.write(exact)
    print(hashlib.sha256(exact).hexdigest())
